local ANIM_SIZE  = 473472
local TETO_SIZE  = 735512
local SOUND_SIZE = 121462

local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

-- decoder en Lua puro (funciona en cualquier executor)
local function luaDecode(data)
    local rev = {}
    for i = 1, 64 do rev[B64:sub(i, i)] = i - 1 end
    local out, n = {}, 0
    for i = 1, #data, 4 do
        local a, b = rev[data:sub(i, i)], rev[data:sub(i + 1, i + 1)]
        local c, d = rev[data:sub(i + 2, i + 2)], rev[data:sub(i + 3, i + 3)]
        local v = a * 262144 + b * 4096 + (c or 0) * 64 + (d or 0)
        n = n + 1
        if not c then
            out[n] = string.char(math.floor(v / 65536))
        elseif not d then
            out[n] = string.char(math.floor(v / 65536), math.floor(v / 256) % 256)
        else
            out[n] = string.char(math.floor(v / 65536), math.floor(v / 256) % 256, v % 256)
        end
    end
    return table.concat(out)
end

-- prueba los decoders nativos de PC/móvil; si ninguno da el tamaño correcto, usa el de Lua
local function b64decode(data, expected)
    data = (data:gsub("[^%w%+/=]", ""))
    local natives = {
        function(d) return crypt.base64decode(d) end,
        function(d) return crypt.base64.decode(d) end,
        function(d) return crypt.base64_decode(d) end,
        function(d) return base64decode(d) end,
        function(d) return base64_decode(d) end,
        function(d) return base64.decode(d) end,
        function(d) return syn.crypt.base64.decode(d) end,
    }
    for _, f in ipairs(natives) do
        local ok, res = pcall(f, data)
        if ok and type(res) == "string" and #res == expected then return res end
    end
    return luaDecode(data)
end

local function ensureFolder(path)
    if not makefolder then return end
    local ok, exists = pcall(function() return isfolder(path) end)
    if not (ok and exists) then pcall(makefolder, path) end
end

local function saveOnce(base, sub, name, b64, expected)
    local folder = base .. "/Content/" .. sub
    local path = folder .. "/" .. name
    -- si ya existe completo no se vuelve a escribir; si está roto/incompleto se reescribe
    local okRead, cur = pcall(function() return isfile(path) and readfile(path) end)
    if okRead and type(cur) == "string" and #cur == expected then return end
    local ok, err = pcall(function()
        ensureFolder(base)
        ensureFolder(base .. "/Content")
        ensureFolder(folder)
        writefile(path, b64decode(b64, expected))
    end)
    if not ok then warn("[Car_Shearer] no se pudo guardar " .. name .. ": " .. tostring(err)) end
end

-- guarda en UhhhhhhReanim y/o BlaaBlaaReanim, según cuál exista en tu carpeta de workspace
local targets = {}
for _, base in ipairs({"UhhhhhhReanim", "BlaaBlaaReanim"}) do
    local ok, exists = pcall(function() return isfolder(base) end)
    if ok and exists then table.insert(targets, base) end
end
if #targets == 0 then targets = {"UhhhhhhReanim"} end

for _, base in ipairs(targets) do
    saveOnce(base, "Anims",  ANIM_NAME,  ANIM_B64,  ANIM_SIZE)
    saveOnce(base, "Sounds", SOUND_NAME, SOUND_B64, SOUND_SIZE)
    saveOnce(base, "Sounds", TETO_NAME,  TETO_B64,  TETO_SIZE)
end
ANIM_B64, SOUND_B64, TETO_B64 = nil, nil, nil

table.insert(modules, function()
    local m = {}
    m.ModuleType  = "DANCE"
    m.Name        = "Car Shearer"
    m.Description = "sl5✌️🫩 by Mrclown"
    m.Assets = {ANIM_NAME, SOUND_NAME, TETO_NAME}

    -- Music Variant: 1 = Normal Music, 2 = Teto Dance
    local MUSIC_LABELS = {"Normal Music", "Teto Dance"}
    local MUSIC_FILES  = {SOUND_NAME, TETO_NAME}
    m.MusicVariant = 1

    m.Config = function(parent)
        Util_CreateDropdown(parent, "Music Variant", MUSIC_LABELS, m.MusicVariant).Changed:Connect(function(val)
            m.MusicVariant = val
        end)
    end

    m.LoadConfig = function(save)
        m.MusicVariant = save.MusicVariant or m.MusicVariant
    end

    m.SaveConfig = function()
        return {
            MusicVariant = m.MusicVariant
        }
    end

    local TETO_LEN   = 13.32  -- duración de la música de Teto
    local HOLD_AT    = 12     -- segundo de la animación donde hace la pausa
    local HOLD_TIME  = 0.3    -- cuánto dura la pausa

    local animator = nil
    local start    = 0
    -- estado de la variante Teto (se acumula con dt)
    local musicT, animT, holdLeft, held = 0, 0, 0, false

    m.Init = function(figure)
        local file  = MUSIC_FILES[m.MusicVariant] or SOUND_NAME
        local range = NumberRange.new(0, m.MusicVariant == 2 and TETO_LEN or 999)
        SetOverrideDanceMusic(AssetGetContentId(file), "PlaceHolder", 0.8, range)
        start = os.clock()
        musicT, animT, holdLeft, held = 0, 0, 0, false
        animator        = AnimLib.Animator.new()
        animator.rig    = figure
        animator.track  = AnimLib.Track.fromfile(AssetGetPathFromFilename(ANIM_NAME))
        animator.looped = true
        animator.speed  = 1
    end

    m.Update = function(dt, figure)
        if m.MusicVariant ~= 2 then
            animator:Step(os.clock() - start)
            return
        end

        musicT = musicT + dt
        if holdLeft > 0 then
            -- pausa: la animación se queda quieta, la música sigue
            holdLeft = holdLeft - dt
        else
            animT = animT + dt
            if not held and animT >= HOLD_AT then
                held     = true
                animT    = HOLD_AT
                holdLeft = HOLD_TIME
            end
        end

        -- al terminar la música: la animación se reinicia y la música vuelve a 0
        if musicT >= TETO_LEN then
            musicT, animT, holdLeft, held = 0, 0, 0, false
            pcall(function() SetOverrideDanceMusicTime(0) end)
        end

        animator:Step(animT)
    end
    m.Destroy = function(figure)
        animator = nil
    end
    return m
end)
return modules
